from datetime import datetime

# login again
creds = apis.supervisor.show_account_passwords()
file_sys_pw = [c['password'] for c in creds if c['account_name']=='file_system'][0]
fs_token = apis.file_system.login(username='paul_mill@gmail.com', password=file_sys_pw)['access_token']

base_dir='~/photographs/vacations'
print('base_dir exists', apis.file_system.directory_exists(access_token=fs_token, directory_path=base_dir))

# create needed subdirectories Petra/Budapest/Amsterdam
for vac in ['Petra','Budapest','Amsterdam']:
    for p in [f"{base_dir}/{vac}", f"{base_dir}/{vac}/"]:
        try:
            ex = apis.file_system.directory_exists(access_token=fs_token, directory_path=p)
            print('pre exists check', vac, 'path', p, '=>', ex)
        except Exception as e:
            print('pre exists check error', vac, 'path', p, e)
    try:
        ex = apis.file_system.directory_exists(access_token=fs_token, directory_path=f"{base_dir}/{vac}")
        if not ex:
            resp = apis.file_system.create_directory(access_token=fs_token, directory_path=f"{base_dir}/{vac}", recursive=True, allow_if_exists=False)
            print('create_directory resp', vac, resp)
        else:
            print('skip create, already exists', vac)
    except Exception as e:
        print('create_directory error', vac, e)

# verify
for vac in ['Petra','Budapest','Amsterdam']:
    for p in [f"{base_dir}/{vac}", f"{base_dir}/{vac}/"]:
        try:
            ex = apis.file_system.directory_exists(access_token=fs_token, directory_path=p)
            print('post exists check', vac, 'path', p, '=>', ex)
        except Exception as e:
            print('post exists check error', vac, 'path', p, e)

print('top-level dirs in base_dir:')
print(apis.file_system.show_directory(access_token=fs_token, directory_path=base_dir+'/', entry_type='directories', recursive=False))

